import java.io.IOException;
import java.io.InputStreamReader;

public class MainProgram {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int totalChars = Integer.parseInt(br.readLine());
        int maxSequence = 0, totalWords = 0, countOutside = 0, countInside = 0;
        boolean inParentheses = false;
        String inputLine = br.readLine();
        char[] characters = inputLine.toCharArray();

        for (int index = 0; index < totalChars; index++) {
            char ch = characters[index];
            if (ch == '(') {
                inParentheses = true;
                countOutside = 0;
            } else if (ch == ')') {
                inParentheses = false;
                if (countInside > 0) {
                    totalWords++;
                    countInside = 0;
                }
            } else {
                if (inParentheses) {
                    if (ch != '_') {
                        countInside++;
                    } else {
                        if (countInside > 0) {
                            totalWords++;
                            countInside = 0;
                        }
                    }
                } else {
                    if (ch != '_') {
                        countOutside++;
                    } else {
                        countOutside = 0;
                    }
                }
            }
            if (countOutside >= maxSequence) {
                maxSequence = countOutside;
            }
        }
        System.out.println(maxSequence);
        System.out.println(totalWords);
    }
}
